    n_str = str(n)

    # An undulating number must have at least 3 digits
    if len(n_str) <= 2:
        return False

    # Check if the number follows the pattern ABAB...
    # The first two digits must be different (A != B)
    if n_str[0] == n_str[1]:
        return False

