def search(arr):
    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        # If mid is even, the pair is (mid, mid+1)
        # If mid is odd, the pair is (mid-1, mid)
        if mid % 2 == 1:
            if arr[mid] == arr[mid + 1]:
                left = mid + 2
            else:
                right = mid
        else:
            if arr[mid] == arr[mid - 1]:
                left = mid + 1
            else:
                right = mid

    return arr[left]
