def is_majority(arr, n, x):
    # Find the first occurrence of x
    first = binary_search_first(arr, 0, n - 1, x)
    if first == -1:
        return False

    # If the first occurrence + n//2 goes beyond the array, it can't be a majority
    if first + n // 2 >= n:
        return False

    # Check if the element at the potential majority index is still x
    return arr[first + n // 2] == x

def binary_search_first(arr, low, high, x):
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            result = mid
            high = mid - 1  # Continue searching in the left half
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result
```

