def get_total_number_of_sequences(m, n):
    # dp[i][j] represents the number of valid sequences of length j ending with value i
    # We only need to track up to value m.
    # Base case: sequences of length 1 ending at i is 1 for all i >= 1.

    # Initialize DP table: (m+1) rows (0 to m), (n+1) columns (0 to n)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: Length 1
    for i in range(1, m + 1):
        dp[i][1] = 1

    # Fill table for lengths 2 to n
    for length in range(2, n + 1):
        for current_val in range(1, m + 1):
            # The previous element 'prev' must satisfy:
            # 1 <= prev <= current_val // 2
            # So we sum dp[prev][length-1] for all valid prev
            if current_val >= 2:
                dp[current_val][length] = sum(dp[prev][length - 1] for prev in range(1, (current_val // 2) + 1))
            else:
                dp[current_val][length] = 0

    # Sum all sequences of length n ending at any value from 1 to m
    return sum(dp[i][n] for i in range(1, m + 1))
```

