def max_sum(arr): 
    n = len(arr)
    if n == 0:
        return 0

    # LIS from left to right ending at i
    lis = arr[:]
    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                if lis[i] < lis[j] + arr[i]:
                    lis[i] = lis[j] + arr[i]

    # LDS from right to left starting at i (which corresponds to decreasing sequence going leftwards from i)
    # We want the sum of a sequence that increases up to i and then decreases.
    # So we need the max decreasing sum starting at i going to the right.
    # Let's compute lds[i] = max sum of decreasing subsequence starting at i going to the right.
    lds = arr[:]
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                if lds[i] < lds[j] + arr[i]:
                    lds[i] = lds[j] + arr[i]

    max_total = 0
    for i in range(n):
        # The peak is arr[i].
        # We add the LIS ending at i and the LDS starting at i.
        # However, arr[i] is counted in both lis[i] and lds[i], so we subtract it once.
        current_sum = lis[i] + lds[i] - arr[i]
        if current_sum > max_total:
            max_total = current_sum

    return max_total
```

