def sumofFactors(n):
    if n <= 0:
        return 0

    total = 0
    # Check all numbers from 1 to n/2 (factors can't be larger than n/2 except n itself)
    # Since we only want even factors, we can iterate efficiently or check divisibility.
    # A simple loop up to n is safe for typical release constraints unless n is huge.
    # Optimization: Iterate only up to sqrt(n) and add both factors if even.

    i = 1
    while i * i <= n:
        if n % i == 0:
            # i is a factor
            if i % 2 == 0:
                total += i

            # n // i is the corresponding factor
            if i * i != n:
                other = n // i
                if other % 2 == 0:
                    total += other
        i += 1

    return total
