def is_majority(arr, n, x):
    # Check if x exists in the array first
    # Since the array is sorted, we can check the first and last occurrence
    # If x is not present, it cannot be a majority element.

    # Find the first occurrence of x
    low, high = 0, n - 1
    first_occurrence = -1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] != x:
                first_occurrence = mid
                break
            else:
                high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    if first_occurrence == -1:
        return False

    # Find the last occurrence of x
    low, high = 0, n - 1
    last_occurrence = -1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            if mid == n - 1 or arr[mid + 1] != x:
                last_occurrence = mid
                break
            else:
                low = mid + 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    if last_occurrence == -1:
        return False

    count = last_occurrence - first_occurrence + 1
    return count > n // 2
```

