def next_smallest_palindrome(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be non-negative")

    # Special case for single-digit numbers: next is n + 1 unless it's 9
    if n < 10:
        return n + 1 if n != 9 else 11

    # Convert number to list of digits for manipulation
    digits = list(str(n))
    length = len(digits)

    # Check if current number is a palindrome
    is_palindrome = digits == digits[::-1]

    if not is_palindrome:
        # Try to find the next palindrome by incrementing and checking
        num = n + 1
        while True:
            s = str(num)
            if s == s[::-1]:
                return num
            num += 1
    else:
        # It is a palindrome, find the next one
        # Strategy: try to form next palindrome by modifying the left half
        half_len = length // 2
        left_half = digits[:half_len]

        # Try to increment the left half and mirror it
        try:
            # Convert left half to integer, increment, convert back to string
            left_int = int(''.join(left_half))
            next_left = str(left_int + 1)

            # Pad or truncate to maintain correct length for mirroring
            if len(next_left) > half_len:
                # Overflow occurred in left half (e.g., 99 -> 100)
                # Handle cases like 999 -> 1001
                new_digits = str(int(''.join(digits)) + 1)
                return new_digits
            else:
                # Mirror the new left half
                if length % 2 == 0:
                    right_half = next_left[::-1]
                else:
                    right_half = next_left[-2::-1]
                new_digits = next_left + right_half
                return int(new_digits)
        except ValueError:
            # Fallback if logic fails (shouldn't happen with correct logic above)
            num = n + 1
            while True:
                s = str(num)
                if s == s[::-1]:
                    return num
                num += 1
