def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        else:
            g, u, v = extended_gcd(y, x % y)
            return g, v, u - (x // y) * v

    g, x0, y0 = extended_gcd(a, b)

    if n % g != 0:
        return None

    factor = n // g
    return (x0 * factor, y0 * factor)
