def is_majority(arr, n, elem):
    if n == 0:
        return False
    # In a sorted array, if an element is the majority,
    # it must appear at index n//2.
    if arr[n // 2] != elem:
        return False
    # Count occurrences of elem
    count = 0
    for x in arr:
        if x == elem:
            count += 1
        else:
            break
    return count > n // 2
