def get_max_sum(n: int) -> int:
    if n <= 0:
        return 0
    if n == 1:
        return 1

    memo = {0: 0, 1: 1}

    def helper(x):
        if x in memo:
            return memo[x]
        # Recursively compute max of (f(x/2) + f(x/3) + f(x/4) + f(x/5)) vs x
        val = max(
            helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5),
            x
        )
        memo[x] = val
        return val

    return helper(n)
