def is_woodall(n):
    if n < 0:
        return False
    if n == 0:
        return False
    if n == 1:
        return False  # 1 is not a Woodall number (W_1 = 1*2^1 - 1 = 1, but convention starts at n=1 => W_1 = 1)

    # Woodall numbers are of the form n * 2^n - 1 for n >= 1
    # So we check if there exists some k such that n = k * 2^k - 1
    k = 1
    while True:
        woodall_num = k * (2 ** k) - 1
        if woodall_num == n:
            return True
        if woodall_num > n:
            return False
        k += 1
